178	  abstract T doTransform(F function, @ParametricNullness I result) throws Exception;
179	
180	  /** Template method for subtypes to actually set the result. */
181	  @ForOverride
182	  abstract void setResult(@ParametricNullness T result);
183	
184	  @Override
185	  protected final void afterDone() {
186	    @RetainedLocalRef ListenableFuture<? extends I> localInputFuture = inputFuture;
